import { expect, test } from '../fixtures';

// Starts from the bob session, not the default one.
test.use({ storageState: process.env.SOVA_AUTH_STATE_BOB! });

test('Email taken', async ({ page }) => {
  await test.step('Open the email settings', async () => {
    await page.goto('/user/settings/email');
  });

  await test.step('Type the current email', async () => {
    await page.getByRole('textbox', { name: 'Old email address', exact: true }).fill('bob@example.com');
  });

  await test.step('Type an email another member uses', async () => {
    await page.getByRole('textbox', { name: 'New email address', exact: true }).fill('alice@example.com');
  });

  await test.step('Repeat it', async () => {
    await page.getByRole('textbox', { name: 'Confirm email address', exact: true }).fill('alice@example.com');
  });

  await test.step('Press Save', async () => {
    await page.getByRole('button', { name: 'Save', exact: true }).click();
  });

  await test.step('The error says the email is taken [code]', async () => {
    await expect(page.locator('.invalid-feedback')).toContainText('alice@example.com is already registered');
  });
});
